def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

print(f'29 is prime: {is_prime(29)}')

class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount <= self.balance:
            self.balance -= amount

acc = BankAccount('Sameer', 1000)
acc.deposit(500)
acc.withdraw(300)
print(f'{acc.owner} balance: {acc.balance}')

