class Student:
    def __init__(self, name, cgpa):
        self.name = name
        self.cgpa = cgpa

class ScholarshipStudent(Student):
    def __init__(self, name, cgpa, scholarship_pct):
        super().__init__(name, cgpa)
        self.scholarship_pct = scholarship_pct

    def get_details(self):
        return f'{self.name} - CGPA: {self.cgpa} - Scholarship: {self.scholarship_pct}%'

s = ScholarshipStudent('Aanya', 9.6, 50)
print(s.get_details())

