def trace_call(func):
    # Decorator that prints CALLING: func, runs func and prints result, then FINISHED: func
    pass

@trace_call
def greet(name):
    return f'Hello {name}!'

greet('Priya')

solution_code:
def trace_call(func):
    def wrapper(*args, **kwargs):
        print(f'CALLING: {func.__name__}')
        result = func(*args, **kwargs)
        print(result)
        print(f'FINISHED: {func.__name__}')
        return result
    return wrapper

@trace_call
def greet(name):
    return f'Hello {name}!'

greet('Priya')

